    "categoryName": "ประเภทที่ 2 สนับสนุนและส่งเสริมการจัดกระบวนการหรือกิจกรรมสร้างเสริมสุขภาพ และการป้องกันโรคขององค์กรหรือกลุ่มประชาชน [ข้อ 10 (2)]",
    "proposingOrg": "กองทุนสวัสดิการชุมชนฯ",
    "activities": "1. กิจกรรมให้ความรู้เรื่องการดูแลสุขภาพผู้สูงวัย ให้ห่างไกลโรค\n2. กิจกรรมฝึกบริหารสมองเพื่อกระตุ้นกระบวนความคิดและการสั่งงานของสมอง\n  - เสียงเพลงเพื่อสุขภาพ\n  - เพลงประกอบท่าทาง\n  - เกมส์ฝึกความจำ\n  - เกมส์จับผิดภาพ\n  - เกมส์บิงโก   \n  - กิจกรรมแลกเปลี่ยนเรียนรู้\n3. ติดตามและประเมินผล",
    "objectives": "1. เพื่อให้ผู้สูงวัยมีความรู้และทักษะในการดูแลตนเอง\n\n2. เพื่อสร้างเสริมและผ่อนคลาย ลดความเครียด\n\n3. เพื่อให้ผู้สูงวัยมีสุขภาพจิต และสุขภาพกายที่ดี",
