    "activities": "1.กิจกรรมให้ความรู้แก่กลุ่มเสี่ยงและแกนนำชุมชน เรื่อง โรคเบาหวาน โรคความดันโลหิตสูงและการปรับเปลี่ยนพฤติกรรมสุขภาพด้วยหลัก 3อ.2ส.\n2.อสม.ลงพื้นที่ติดตามผลวัดความดันโลหิต หาค่าBMI 2ครั้ง/เดือนเป็นเวลา3เดือน\n3.รายงานผล",
