    "projectName": "โครงการอบรมให้ความรู้เกี่ยวกับการปฐมพยาบาลเบื้องต้น และการช่วยฟื้นคืนชีพ (CPR)",
    "categoryNumber": 2,
    "categoryName": "ประเภทที่ 2 สนับสนุนและส่งเสริมการจัดกระบวนการหรือกิจกรรมสร้างเสริมสุขภาพ และการป้องกันโรคขององค์กรหรือกลุ่มประชาชน [ข้อ 10 (2)]",
    "proposingOrg": "รร.บ้านป่าเตียว",
    "activities": "1. โรงเรียนบ้านป่าเตียวจัดกิจกรรมให้ความรู้ เรื่องการปฐมพยาบาลเบื้องต้น และการช่วยฟื้นคืนชีพ (CPR)\n\n2. กิจกรรมฐานการเรียนรู้ ฐานที่ 1 ฐานยาสามัญประจำบ้าน\nฐานที่ 2 ฐานการทำแผลอย่างถูกวิธี\nฐานที่ 3 การช่วยฟื้นคืนชีพ (CPR)",
    "objectives": "1. เพื่อให้นักเรียนและครู มีความรู้ ความเข้าใจ เรื่องการปฐมพยาบาลเบื้องต้น และการช่วยฟื้นคืนชีพ (CPR)\n- การแนะนำยาสามัญประจำบ้าน\n- การแนะนำอุปกรณ์ที่เกี่ยวข้องกับการปฐมพยาบาลเบื้องต้น \n- การปฐมพยาบาลผู้ป่วยภาวะฉุกเฉิน     \n- การช่วยเหลือผู้ป่วย\n- การทำแผลอย่างถูกวิธี \n- สอน/สาธิตการทำ CPR ฟื้นคืนชีพ \n- ฝึกการปฎิบัติการทำ CPR ฟื้นคืนชีพ",
    "targetGroup": "1 .นักเรียนชั้นประถมศึกษาปีที่ 1 - 6 จำนวน 46 คน\n\n2. ครูผู้สังเกตการณ์ 12 คน\n\n\nรวม 58 คน",
