    "projectCode": "กองทุน-69-018",
    "projectName": "โครงการส่งเสริมพัฒนาการทั้ง 4 ด้าน ในเด็กปฐมวัยโรงเรียนบ้านป่าเตียว",
    "categoryNumber": 2,
    "categoryName": "ประเภทที่ 2 สนับสนุนและส่งเสริมการจัดกระบวนการหรือกิจกรรมสร้างเสริมสุขภาพ และการป้องกันโรคขององค์กรหรือกลุ่มประชาชน [ข้อ 10 (2)]",
    "proposingOrg": "รร.บ้านป่าเตียว",
    "activities": "1. กิจกรรมอบรมให้ความรู้พัฒนาการทั้ง 4 ด้าน ในเด็กปฐมวัย \n\n2. กิจกรรมฝึกทักษะผ่านฐานการเรียนรู้\nฐานที่ 1 กิจกรรมระบายสีปูนปลาสเตอร์\nฐานที่ 2 กิจกรรมผ้ามัดย้อม\nฐานที่ 3 กิจกรรมอาหารสร้างสรรค์ส่งเสริมสุขภาพ",
    "objectives": "1. เพื่อส่งเสริมการเรียนรู้ด้านสุขภาพนักเรียนตามฐานการเรียนรู้ต่างๆ และสามารถนำความรู้ที่ได้ไปใช้ในชีวิตประจำวัน  \n             \n2. เพื่อส่งเสริมการพัฒนาทั้ง 4 ด้าน คือ ร่างกาย อารมณ์ สังคมและ สติปัญญา \n                           \n3. เพื่อให้เด็กปฐมวัยมีสุขภาพกายและสุขภาพจิตที่ดี  \n                      \n4. เพื่อให้เด็กปฐมวัยมีสุขภาพร่างกายแข็งแรง และสร้างความสามัคคีเป็นหมู่คณะ",
    "targetGroup": "1 .นักเรียนชั้นอนุบาลปีที่ 1 – 3 จำนวน 39 คน\n\n2. ครูและบุคลากรทางการศึกษา จำนวน 5 คน\n\nรวม 44 คน",
    "kpi": "1.ร้อยละ 80 นักเรียนสามารถเรียนรู้ตามฐานการเรียนรู้ต่างๆ และสามารถนำความรู้ที่ได้ไปใช้ใชีวิตประจำวันได้ \n             \n2. ร้อยละ 80 นักเรียนมีพัฒนาทั้ง 4 ด้านดีขึ้น\n                           \n3. ร้อยละ 80 เด็กปฐมวัยมีสุขภาพกายและสุขภาพจิตที่ดี  \n                      \n4. ร้อยละ 80 เด็กปฐมวัยมีสุขภาพร่างกายแข็งแรง และมีความสามัคคีเป็นหมู่คณะ",
