    "categoryName": "ประเภทที่ 3 สนับสนุนและส่งเสริมการจัดบริการสาธารณสุขของศูนย์ฯ หรือหน่วยงานที่รับผิดชอบศูนย์ฯ (เด็กเล็ก/ผู้สูงอายุ/คนพิการ) [ข้อ 10 (3)]",
    "proposingOrg": "ศพด.บ้านควนทองสีห์",
