    "objectives": "1. เพื่อรณรงค์ให้เด็กศูนย์พัฒนาเด็กเล็กบ้านควนทองสีห์ สวมหมวกนิรภัยและได้มาตรฐานขณะเดินทางด้วยรถจักรยานยนต์\n\n2. เพื่อให้ครูและผู้ปกครองมีความรู้ความเข้าใจเกี่ยวกับกฎระเบียบวินัยจราจร และการใช้รถใช้ถนนให้ปลอดภัย",
    "targetGroup": "1. เด็กในศูนย์พัฒนาเด็กเล็กบ้านควนทองสีห์ จำนวน 20 คน \n\n2. ผู้ปกครองจำนวน 20 คน\n\n3. ครูผู้สังเกตการณ์ 2 คน\n\nรวม 42 คน",
    "kpi": "1. ร้อยละ 90 ของเด็กในศูนย์พัฒนาเด็กเล็กบ้านควนทองสีห์สวมหมวกนิรภัยขณะเดินทางด้วยรถจักรยานยนต์\n\n2. ร้อยละ 80 ของครู ผู้ปกครอง และเด็กในศูนย์พัฒนาเด็กเล็กบ้านควนทองสีห์มีความรู้ความเข้าใจเกี่ยวกับกฎระเบียบวินัยจราจร และการใช้รถใช้ถนนให้ปลอดภัย",
